-- Mubest Digital CMS schema. The Vercel API also creates these tables automatically.
CREATE TABLE IF NOT EXISTS admin_users (id BIGSERIAL PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS admin_sessions (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_settings (key TEXT PRIMARY KEY,value JSONB NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_pages (slug TEXT PRIMARY KEY,draft JSONB NOT NULL DEFAULT '{}'::jsonb,published JSONB NOT NULL DEFAULT '{}'::jsonb,status TEXT NOT NULL DEFAULT 'published',updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),published_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS portfolio_projects (id BIGSERIAL PRIMARY KEY,slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,category TEXT DEFAULT '',excerpt TEXT DEFAULT '',description TEXT DEFAULT '',cover_image TEXT DEFAULT '',gallery JSONB NOT NULL DEFAULT '[]'::jsonb,project_url TEXT DEFAULT '',featured BOOLEAN NOT NULL DEFAULT FALSE,sort_order INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),published_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS services (id BIGSERIAL PRIMARY KEY,slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,summary TEXT DEFAULT '',description TEXT DEFAULT '',tag TEXT DEFAULT '',icon TEXT DEFAULT 'website',deliverables JSONB NOT NULL DEFAULT '[]'::jsonb,sort_order INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'published',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS testimonials (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,role TEXT DEFAULT '',company TEXT DEFAULT '',quote TEXT NOT NULL,avatar_url TEXT DEFAULT '',rating INTEGER NOT NULL DEFAULT 5,sort_order INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS faqs (id BIGSERIAL PRIMARY KEY,question TEXT NOT NULL,answer TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'published',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS media_assets (id BIGSERIAL PRIMARY KEY,url TEXT NOT NULL UNIQUE,pathname TEXT DEFAULT '',filename TEXT DEFAULT '',content_type TEXT DEFAULT '',size_bytes BIGINT NOT NULL DEFAULT 0,alt_text TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS leads (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,service TEXT DEFAULT '',budget TEXT DEFAULT '',message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',notes TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES admin_users(id) ON DELETE SET NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT DEFAULT '',summary TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS content_revisions (id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES admin_users(id) ON DELETE SET NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,snapshot JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
